# DK SKR.  Silkeborg - Kjellerup - Rødkærsbro
#
let sr = path("d3.dk.skr");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Silkeborg  dk.SBS

    with link = "line.dk.SKR" {
        track(:lor, sr[:sil.yh + 0.49seg, :sil.yr] >> 1mo);
        track(:lor, sr[:sil.yr - 0.1dl, :lys - 0.49sw] >> 1mo);
    }

    with link = "point.dk.Lysbro", railway = :station {
        track(sr[:lys - 0.5sw, :lys + 0.5sw] >> 1mo);
        marker(:right :de.bf, sr[:lys] >> 1mo >> 0.5mt);
        station(:top, sr[:lys] >> 1mo >> 0.5mt >> 1sh + (-0.5dt, -0.8dt),
            "Lysbro", "SKR: 3,1"
        );
    }

    with link = "line.dk.SKR" {
        track(
                sr[:lys + 0.49sw, :lys + 0.5sw] >> 1mo
            ..  sr[:sil.xr + 2mo, :sil.xr + 1.21km]
        );
        line_label(:left:ne, sr[:sil.xr + 1.2km] << 0.5mt, "SKR");
        track(sr[:sil.xr + 1.19km, :hvi - 0.49sw]);
    }

    with link = "point.dk.Hvinningdal", railway = :station {
        track(sr[:hvi - 0.5sw, :hvi + 0.5sw]);
        marker(:right :de.hp, sr[:hvi] >> 0.5mt);
        station(:right, sr[:hvi] >> 0.5mt >> 1sh + (1.8dt, 1.8dt),
            "Hvinningdal", "SKR: 6,3"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:hvi + 0.49sw, :obo - 0.49sw]);
    }

    with link = "point.dk.Øster-Bording", railway = :station {
        track(sr[:obo - 0.5sw, :obo + 0.5sw]);
        marker(:left :de.bf, sr[:obo] << 0.5mt);
        station(:left, sr[:obo] << 0.5mt << 1sh + (-1.8dt, 1dt),
            "Øster Bording", "SKR: 8,0"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:obo + 0.49sw, :ska - 0.49sw]);
    }

    with link = "point.dk.Skægkær", railway = :station {
        track(sr[:ska - 0.5sw, :ska + 0.5sw]);
        marker(:right :de.bf, sr[:ska] >> 0.5mt);
        station(:right, sr[:ska] >> 0.5mt >> 1sh + (1.5dt, 1.3dt),
            "Skægkær", "SKR: 10,2"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:ska + 0.49sw, :ore - 0.49sw]);
    }

    with link = "point.dk.Ørevadbro", railway = :station {
        track(sr[:ore - 0.5sw, :ore + 0.5sw]);
        marker(:right :de.hp, sr[:ore] >> 0.5mt);
        station(:right, sr[:ore] >> 0.5mt >> 1sh + (1.8dt, 1.8dt),
            "Ørevadbro", "SKR: 12,1"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:ore + 0.49sw, :lem - 0.49sw]);
    }

    with link = "point.dk.Lemming", railway = :station {
        track(sr[:lem - 0.5sw, :lem + 0.5sw]);
        marker(:right :de.bf, sr[:lem] >> 0.5mt);
        station(:right, sr[:lem] >> 0.5mt >> 1sh + (1.5dt, 1.3dt),
            "Lemming", "SKR: 14,8"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:lem + 0.49sw, :lem + 2.01km]);
        line_label(:right:w, sr[:lem + 2km] >> 0.5mt, (0dt, -0.4dt), "SKR");
        track(sr[:lem + 1.99km, :hig - 0.49sw]);
    }

    with link = "point.dk.Hinge", railway = :station {
        track(sr[:hig - 0.5sw, :hig + 0.5sw]);
        marker(:right :de.bf, sr[:hig] >> 0.5mt);
        station(:top, sr[:hig] >> 0.5mt >> 1sh >> 0.6dt,
            "Hinge", "SKR: 18,1"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:hig + 0.49sw, :nor - 0.49sw]);
    }

    with link = "point.dk.Nørskovlund", railway = :station {
        track(sr[:nor - 0.5sw, :nor + 0.5sw]);
        marker(:left :de.hp, sr[:nor] << 0.5mt);
        station(:left, sr[:nor] << 0.5mt << 1sh + (-1.8dt, 1.3dt),
            "Nørskovlund", "SKR: 20,2"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:nor + 0.49sw, :hib - 0.49sw]);
    }

    with link = "point.dk.Hindbjerg", railway = :station {
        track(sr[:hib - 0.5sw, :hib + 0.5sw]);
        marker(:right :de.bf, sr[:hib] >> 0.5mt);
        station(:top, sr[:hib] >> 0.5mt >> 1sh >> 0.8dt,
            "Hindbjerg", "SKR: 21,9"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:hib + 0.49sw, :kje - 0.49sw]);
    }

    with link = "point.dk.Kjellerup", railway = :station {
        track(sr[:kje - 0.5sw, :kje + 0.5sw]);
        marker(:left :de.bf, sr[:kje] << 0.5mt);
        station(:left, sr[:kje] << 0.5mt << 1sh + (-1.7dt, 1.7dt),
            span(:bold, "Kjellerup"),
            "SKR: 25,3"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:kje + 0.49sw, :don - 0.49sw]);
    }

    with link = "point.dk.Donsborg", railway = :station {
        track(sr[:don - 0.5sw, :don + 0.5sw]);
        marker(:left :de.hp, sr[:don] << 0.5mt);
        station(:left, sr[:don] << 0.5mt << 1sh + (-1.8dt, 1.4dt),
            "Donsborg", "SKR: 26,6"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:don + 0.49sw, :aun - 0.49sw]);
    }

    with link = "point.dk.Aunsbjerg", railway = :station {
        track(sr[:aun - 0.5sw, :aun + 0.5sw]);
        marker(:left :de.hp, sr[:aun] << 0.5mt);
        station(:left, sr[:aun] << 0.5mt << 1sh + (-2.0dt, 0.3dt),
            "Aunsbjerg", "SKR: 28,7"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:aun + 0.49sw, :sjo - 0.49sw]);
    }

    with link = "point.dk.Sjørslev", railway = :station {
        track(sr[:sjo - 0.5sw, :sjo + 0.5sw]);
        marker(:left :de.bf, sr[:sjo] << 0.5mt);
        station(:left, sr[:sjo] << 0.5mt << 1sh + (-1.8dt, 0.8dt),
            "Sjørslev", "SKR: 30,1"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:sjo + 0.49sw, :bre - 0.49sw]);
    }

    with link = "point.dk.Bredmose", railway = :station {
        track(sr[:bre - 0.5sw, :bre + 0.5sw]);
        marker(:left :de.hp, sr[:bre] << 0.5mt);
        station(:top, sr[:bre] << 0.5mt << 1sh + (-1.1dt, -1dt),
            "Bredmose", "SKR: 31,5"
        );
    }

    with link = "line.dk.SKR" {
        track(sr[:bre + 0.49sw, :bre + 1.31km]);
        line_label(:right:n, sr[:bre + 1.3km] >> 0.5mt, (0.5dt, 0dt), "SKR");
        track(sr[:bre + 1.29km, :rod.xs - 1mo]);
        track(:lor,
                sr[:rod.xs - 1.1mo, :rod.xs - 1mo]
            ..  sr[:rod.ys, :rod.ys + 0.1dl] >> 1mo
        );
    }

    # point.dk.Rødkærsbro  dk.LST
}

